head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/controlResize.js");
// 화면 리사이징

scwin.vScrenID = "ULDINS20200.xml";
scwin.cnt = 0;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 일자별  표준코드 조회 
 ***********************************************/
scwin.ins_search = function() {
    if ($c.stf.getObjectValue(ckb_BND) == "N" &&
        $c.stf.getObjectValue(ckb_ELS_DLS) == "N" &&
        $c.stf.getObjectValue(ckb_STKCERT) == "N" &&
        $c.stf.getObjectValue(ckb_BENFCERT) == "N" &&
        $c.stf.getObjectValue(ckb_SUBSRGHT) == "N" &&
        $c.stf.getObjectValue(ckb_STK_WRNT) == "N" &&
        $c.stf.getObjectValue(ckb_DR) == "N" &&
        $c.stf.getObjectValue(ckb_CP) == "N" &&
        $c.stf.getObjectValue(ckb_CD) == "N" &&
        $c.stf.getObjectValue(ckb_INDIC) == "N" &&
        $c.stf.getObjectValue(ckb_FUTOPT) == "N" &&
        $c.stf.getObjectValue(ckb_ETN) == "N" &&
        $c.stf.getObjectValue(ckb_INVST) == "N" &&
        $c.stf.getObjectValue(ckb_GENE) == "N") {
        $c.win.alert("[ 조회조건 부족 ] 유가증권을 선택하십시요");
        return false;
    }
    if ($c.stf.getObjectValue(ckb_ALL_DD) == "N" &&
        $c.stf.getObjectValue(ckb_STD_CD_GRNT_DD) == "N" &&
        $c.stf.getObjectValue(ckb_CONTN_CHG_DD) == "N" &&
        $c.stf.getObjectValue(ckb_EXP_DD) == "N" &&
        $c.stf.getObjectValue(ckb_LST_DD) == "N") {
        $c.win.alert("[ 조회조건 부족 ] 조회기간을 넣어주십시요");
        return false;
    }
    if ($c.stf.getObjectValue(ckb_ALL_DD) == "Y") {
        if ($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE) != "" &&
            $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE).length == 8 &&
            $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE) != "" &&
            $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE).length == 8) {

        } else {
            $c.win.alert("[조회조건 부족] 표준코드부여일 조건 확인요망");
            return false;
        }
        if ($c.stf.getObjectValue(edt_pCONTN_CHG_DD_SDATE) != "" &&
            $c.stf.getObjectValue(edt_pCONTN_CHG_DD_SDATE).length == 8 &&
            $c.stf.getObjectValue(edt_pCONTN_CHG_DD_EDATE) != "" &&
            $c.stf.getObjectValue(edt_pCONTN_CHG_DD_EDATE).length == 8) {

        } else {
            $c.win.alert("[조회조건 부족] 내용변경일 조건 확인요망");
            return false;
        }
        if ($c.stf.getObjectValue(edt_pEXP_DD_SDATE) != "" &&
            $c.stf.getObjectValue(edt_pEXP_DD_SDATE).length == 8 &&
            $c.stf.getObjectValue(edt_pEXP_DD_EDATE) != "" &&
            $c.stf.getObjectValue(edt_pEXP_DD_EDATE).length == 8) {

        } else {
            $c.win.alert("[조회조건 부족] 만기일(상환일) 조건 확인요망");
            return false;
        }

        // 검색일 체크
        if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
            return false;
        }

        // 검색일 체크
        if ($c.stf.compareFromToDate2(edt_pCONTN_CHG_DD_SDATE, edt_pCONTN_CHG_DD_EDATE) == false) {
            return false;
        }

        // 검색일 체크
        if ($c.stf.compareFromToDate2(edt_pEXP_DD_SDATE, edt_pEXP_DD_EDATE) == false) {
            return false;
        }
    } else {
        if ($c.stf.getObjectValue(ckb_STD_CD_GRNT_DD) == "Y") {
            if ($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE) != "" &&
                $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE).length == 8 &&
                $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE) != "" &&
                $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE).length == 8) {

            } else {
                $c.win.alert("[조회조건 부족] 표준코드부여일 조건 확인요망");
                return false;
            }

            // 검색일 체크
            if ($c.stf.compareFromToDate2(edt_pSTD_CD_GRNT_DD_SDATE, edt_pSTD_CD_GRNT_DD_EDATE) == false) {
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_CONTN_CHG_DD) == "Y") {
            if ($c.stf.getObjectValue(edt_pCONTN_CHG_DD_SDATE) != "" &&
                $c.stf.getObjectValue(edt_pCONTN_CHG_DD_SDATE).length == 8 &&
                $c.stf.getObjectValue(edt_pCONTN_CHG_DD_EDATE) != "" &&
                $c.stf.getObjectValue(edt_pCONTN_CHG_DD_EDATE).length == 8) {

            } else {
                $c.win.alert("[조회조건 부족] 내용변경일 조건 확인요망");
                return false;
            }

            // 검색일 체크
            if ($c.stf.compareFromToDate2(edt_pCONTN_CHG_DD_SDATE, edt_pCONTN_CHG_DD_EDATE) == false) {
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_EXP_DD) == "Y") {
            if ($c.stf.getObjectValue(edt_pEXP_DD_SDATE) != "" &&
                $c.stf.getObjectValue(edt_pEXP_DD_SDATE).length == 8 &&
                $c.stf.getObjectValue(edt_pEXP_DD_EDATE) != "" &&
                $c.stf.getObjectValue(edt_pEXP_DD_EDATE).length == 8) {

            } else {
                $c.win.alert("[조회조건 부족] 만기일(상환일) 조건 확인요망");
                return false;
            }

            // 검색일 체크
            if ($c.stf.compareFromToDate2(edt_pEXP_DD_SDATE, edt_pEXP_DD_EDATE) == false) {
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_LST_DD) == "Y") {
            if ($c.stf.getObjectValue(edt_pLST_DD_SDATE) != "" &&
                $c.stf.getObjectValue(edt_pLST_DD_SDATE).length == 8 &&
                $c.stf.getObjectValue(edt_pLST_DD_EDATE) != "" &&
                $c.stf.getObjectValue(edt_pLST_DD_EDATE).length == 8) {

            } else {
                $c.win.alert("[조회조건 부족] 상장일 조건 확인요망");
                return false;
            }

            // 검색일 체크
            if ($c.stf.compareFromToDate2(edt_pLST_DD_SDATE, edt_pLST_DD_EDATE) == false) {
                return false;
            }
        }
    }

    //조회기간체크
    var v_AllChecked = $c.stf.getObjectValue(ckb_ALL);
    //상품 전체선택
    if (v_AllChecked == 'Y') {
        if ($c.stf.getObjectValue(ckb_STD_CD_GRNT_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE) != "") &&
                eval(cGetPlusMonth2(edt_pSTD_CD_GRNT_DD_SDATE.getValue(), 6)) < eval(edt_pSTD_CD_GRNT_DD_EDATE.getValue())) {
                $c.win.alert("전체선택시 코드부여일의 검색 기간은 6개월 이내로만 가능합니다.");
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_CONTN_CHG_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pCONTN_CHG_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pCONTN_CHG_DD_EDATE) != "") &&
                eval(cGetPlusMonth2(edt_pCONTN_CHG_DD_SDATE.getValue(), 6)) < eval(edt_pCONTN_CHG_DD_EDATE.getValue())) {
                $c.win.alert("전체선택시 내용변경일의 검색 기간은 6개월 이내로만 가능합니다.");
                edt_pCONTN_CHG_DD_SDATE.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_EXP_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pEXP_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pEXP_DD_EDATE) != "") &&
                eval(cGetPlusMonth2(edt_pEXP_DD_SDATE.getValue(), 6)) < eval(edt_pEXP_DD_EDATE.getValue())) {
                $c.win.alert("전체선택시 만기일의 검색 기간은 6개월 이내로만 가능합니다.");
                edt_pEXP_DD_SDATE.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_LST_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pLST_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pLST_DD_EDATE) != "") &&
                eval(cGetPlusMonth2(edt_pLST_DD_SDATE.getValue(), 6)) < eval(edt_pLST_DD_EDATE.getValue())) {
                $c.win.alert("전체선택시 상장일의 검색 기간은 6개월 이내로만 가능합니다.");
                edt_pLST_DD_SDATE.focus();
                return false;
            }
        }

        //전체선택해제

    } else {
        if ($c.stf.getObjectValue(ckb_STD_CD_GRNT_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pSTD_CD_GRNT_DD_EDATE) != "") &&
                eval($c.ut.cGetPlusYear(edt_pSTD_CD_GRNT_DD_SDATE.getValue(), 1)) < eval(edt_pSTD_CD_GRNT_DD_EDATE.getValue())) {
                $c.win.alert("코드부여일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_pSTD_CD_GRNT_DD_SDATE.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_CONTN_CHG_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pCONTN_CHG_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pCONTN_CHG_DD_EDATE) != "") &&
                eval($c.ut.cGetPlusYear(edt_pCONTN_CHG_DD_SDATE.getValue(), 1)) < eval(edt_pCONTN_CHG_DD_EDATE.getValue())) {
                $c.win.alert("내용변경일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_pCONTN_CHG_DD_SDATE.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_EXP_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pEXP_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pEXP_DD_EDATE) != "") &&
                eval($c.ut.cGetPlusYear(edt_pEXP_DD_SDATE.getValue(), 1)) < eval(edt_pEXP_DD_EDATE.getValue())) {
                $c.win.alert("만기일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_pEXP_DD_SDATE.focus();
                return false;
            }
        }
        if ($c.stf.getObjectValue(ckb_LST_DD) == "Y") {
            if (($c.stf.getObjectValue(edt_pLST_DD_SDATE) != "" && $c.stf.getObjectValue(edt_pLST_DD_EDATE) != "") &&
                eval($c.ut.cGetPlusYear(edt_pLST_DD_SDATE.getValue(), 1)) < eval(edt_pLST_DD_EDATE.getValue())) {
                $c.win.alert("상장일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_pLST_DD_SDATE.focus();
                return false;
            }
        }
    }
    var alert_msg = "";
    if ($c.stf.getObjectValue(ckb_STD_CD_GRNT_DD) == "Y") {
        if ($c.stf.getObjectValue(ckb_GENE) == "Y") alert_msg += "일반상품(금,석유,배출권)은 표준코드부여일 검색을 할 수 없습니다. \n";
    }
    if ($c.stf.getObjectValue(ckb_CONTN_CHG_DD) == "Y") {
        if ($c.stf.getObjectValue(ckb_GENE) == "Y") alert_msg += "일반상품(금,석유,배출권)은 내용변경일 검색을 할 수 없습니다. \n";
    }
    if ($c.stf.getObjectValue(ckb_EXP_DD) == "Y") {
        if ($c.stf.getObjectValue(ckb_STKCERT) == "Y") alert_msg += "주권은 만기일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_SUBSRGHT) == "Y") alert_msg += "신주인수권은 만기일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_STK_WRNT) == "Y") alert_msg += "주식워런트(ELW)는 만기일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_DR) == "Y") alert_msg += "예탁증서는 만기일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_INDIC) == "Y") alert_msg += "지표는 만기일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_INVST) == "Y") alert_msg += "투자계약증권은 만기일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_GENE) == "Y") alert_msg += "일반상품(금,석유,배출권)은 만기일 검색을 할 수 없습니다. \n";
    }
    if ($c.stf.getObjectValue(ckb_LST_DD) == "Y") {
        if ($c.stf.getObjectValue(ckb_ELS_DLS) == "Y") alert_msg += "ELS/DLS는 상장일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_INDIC) == "Y") alert_msg += "지표는 상장일 검색을 할수 없습니다 \n";
        if ($c.stf.getObjectValue(ckb_INVST) == "Y") alert_msg += "투자계약증권은 상장일 검색을 할수 없습니다 \n";
    }
    if (alert_msg != "") {
        alert_msg += "\n조회하시겠습니까?";
        if (!confirm(alert_msg)) {
            return;
        }
    }
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS20200_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.etc.select.listEtcIsinUploadInquiry" + "&{P}CKB_BND=" + $c.stf.getObjectValue(ckb_BND) + "&{P}CKB_ETN=" + $c.stf.getObjectValue(ckb_ETN) + "&{P}CKB_ELS_DLS=" + $c.stf.getObjectValue(ckb_ELS_DLS) + "&{P}CKB_STKCERT=" + $c.stf.getObjectValue(ckb_STKCERT) + "&{P}CKB_BENFCERT=" + $c.stf.getObjectValue(ckb_BENFCERT) + "&{P}CKB_SUBSRGHT=" + $c.stf.getObjectValue(ckb_SUBSRGHT) + "&{P}CKB_STK_WRNT=" + $c.stf.getObjectValue(ckb_STK_WRNT) + "&{P}CKB_DR=" + $c.stf.getObjectValue(ckb_DR) + "&{P}CKB_CP=" + $c.stf.getObjectValue(ckb_CP) + "&{P}CKB_CD=" + $c.stf.getObjectValue(ckb_CD) + "&{P}CKB_INDIC=" + $c.stf.getObjectValue(ckb_INDIC) + "&{P}CKB_FUTOPT=" + $c.stf.getObjectValue(ckb_FUTOPT) + "&{P}CKB_INVST=" + $c.stf.getObjectValue(ckb_INVST) + "&{P}CKB_GENE=" + $c.stf.getObjectValue(ckb_GENE) +
        //"&{P}CKB_GREENHOUSE=" +  getObjectValue(ckb_GREENHOUSE) + 
        "&{P}STD_CD_GRNT_DD_SDATE=" + scwin.fn_returnDate(edt_pSTD_CD_GRNT_DD_SDATE) + "&{P}STD_CD_GRNT_DD_EDATE=" + scwin.fn_returnDate(edt_pSTD_CD_GRNT_DD_EDATE) + "&{P}CONTN_CHG_DD_SDATE=" + scwin.fn_returnDate(edt_pCONTN_CHG_DD_SDATE) + "&{P}CONTN_CHG_DD_EDATE=" + scwin.fn_returnDate(edt_pCONTN_CHG_DD_EDATE) + "&{P}EXP_DD_SDATE=" + scwin.fn_returnDate(edt_pEXP_DD_SDATE) + "&{P}EXP_DD_EDATE=" + scwin.fn_returnDate(edt_pEXP_DD_EDATE) + "&{P}LST_DD_SDATE=" + scwin.fn_returnDate(edt_pLST_DD_SDATE) + "&{P}LST_DD_EDATE=" + scwin.fn_returnDate(edt_pLST_DD_EDATE) + "&{P}ISU_NM=" + $c.stf.getObjectValue(txb_pISU_NM);

    //	 alert(url); 
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : fn_AllCheck
 * 설명       : 전체선택 체크 시 체크/언체크.
 ***********************************************/
scwin.fn_AllCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(ckb_ALL);
    var oCheckBoxs = document.getElementsByName("ckb");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
    }
};



/********************************************** 
 * 함수명   : fn_AllDateCheck
 * 설명       : 전체선택 체크 시 체크/언체크.
 ***********************************************/
scwin.fn_AllDateCheck = function() {
    var sAllChecked = $c.stf.getObjectValue(ckb_ALL_DD);
    var oCheckBoxs = document.getElementsByName("ckb_date");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked == "Y") ? true : false);
    }
    if ($c.stf.getObjectValue(ckb_ALL_DD) == "Y") {
        edt_pSTD_CD_GRNT_DD_SDATE.setDisabled(false);
        edt_pSTD_CD_GRNT_DD_EDATE.setDisabled(false);
        edt_pCONTN_CHG_DD_SDATE.setDisabled(false);
        edt_pCONTN_CHG_DD_EDATE.setDisabled(false);
        edt_pEXP_DD_SDATE.setDisabled(false);
        edt_pEXP_DD_EDATE.setDisabled(false);
        edt_pLST_DD_SDATE.setDisabled(false);
        edt_pLST_DD_EDATE.setDisabled(false);
    } else {
        edt_pSTD_CD_GRNT_DD_SDATE.setDisabled(true);
        edt_pSTD_CD_GRNT_DD_EDATE.setDisabled(true);
        edt_pCONTN_CHG_DD_SDATE.setDisabled(true);
        edt_pCONTN_CHG_DD_EDATE.setDisabled(true);
        edt_pEXP_DD_SDATE.setDisabled(true);
        edt_pEXP_DD_EDATE.setDisabled(true);
        edt_pLST_DD_SDATE.setDisabled(true);
        edt_pLST_DD_EDATE.setDisabled(true);
    }
};



/********************************************** 
 * 함수명   : fn_AllDateCheck
 * 설명       : 전체선택 체크 시 체크/언체크.
 ***********************************************/
scwin.fn_ckbCheck = function(Obj) {
    var ckbCount = 0;
    var oCheckBoxs = document.getElementsByName("ckb_date");
    for (var nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        if (oCheckBoxs[nRow].checked == true) ckbCount++;
    }
    if (ckbCount == 3) $c.stf.setObjectValue(ckb_ALL_DD, "Y");

    else $c.stf.setObjectValue(ckb_ALL_DD, "N");
    if (Obj.id == "ckb_STD_CD_GRNT_DD") {
        if ($c.stf.getObjectValue(ckb_STD_CD_GRNT_DD) == "Y") {
            edt_pSTD_CD_GRNT_DD_SDATE.setDisabled(false);
            edt_pSTD_CD_GRNT_DD_EDATE.setDisabled(false);
        } else {
            edt_pSTD_CD_GRNT_DD_SDATE.setDisabled(true);
            edt_pSTD_CD_GRNT_DD_EDATE.setDisabled(true);
        }
    }
    if (Obj.id == "ckb_CONTN_CHG_DD") {
        if ($c.stf.getObjectValue(ckb_CONTN_CHG_DD) == "Y") {
            edt_pCONTN_CHG_DD_SDATE.setDisabled(false);
            edt_pCONTN_CHG_DD_EDATE.setDisabled(false);
        } else {
            edt_pCONTN_CHG_DD_SDATE.setDisabled(true);
            edt_pCONTN_CHG_DD_EDATE.setDisabled(true);
        }
    }
    if (Obj.id == "ckb_EXP_DD") {
        if ($c.stf.getObjectValue(ckb_EXP_DD) == "Y") {
            edt_pEXP_DD_SDATE.setDisabled(false);
            edt_pEXP_DD_EDATE.setDisabled(false);
        } else {
            edt_pEXP_DD_SDATE.setDisabled(true);
            edt_pEXP_DD_EDATE.setDisabled(true);
        }
    }
    if (Obj.id == "ckb_LST_DD") {
        if ($c.stf.getObjectValue(ckb_LST_DD) == "Y") {
            edt_pLST_DD_SDATE.setDisabled(false);
            edt_pLST_DD_EDATE.setDisabled(false);
        } else {
            edt_pLST_DD_SDATE.setDisabled(true);
            edt_pLST_DD_EDATE.setDisabled(true);
        }
    }
};





