scwin.btn_filesave_onclick = function() {
    /*******************************************************************************
     *  [ 표준코드 앞 6자리가 아래와 같을 경우 발행기관명과 약명을  지정된 명을 사용한다.
     *  표준코드6자리 종목명                     발행기관명                   발행기관약명
     *  KR1011      국고채권(사용금지)          THE REPUBLIC OF KOREA       KOREA
     *  KR1013      국민주택기금채권            THE REPUBLIC OF KOREA       KOREA
     *  KR1015      제1종국민주택채권           THE REPUBLIC OF KOREA       KOREA
     *  KR1017      제2종국민주책채권           THE REPUBLIC OF KOREA       KOREA
     *  KR1019      국민투자채권                THE REPUBLIC OF KOREA       KOREA
     *  KR1021      농어촌발전채권              THE REPUBLIC OF KOREA       KOREA
     *  KR1023      농지채권                   THE REPUBLIC OF KOREA       KOREA
     *  KR1025      양곡기금채권                THE REPUBLIC OF KOREA       KOREA
     *  KR1027      외국환평형기금채권          THE REPUBLIC OF KOREA       KOREA
     *  KR1029      징발보상증권                THE REPUBLIC OF KOREA       KOREA
     *  KR1031      재정증권                   THE REPUBLIC OF KOREA       KOREA
     *  KR1033      철도증권                   THE REPUBLIC OF KOREA       KOREA
     *  KR1035      국고채권                   THE REPUBLIC OF KOREA       KOREA
     *  KR1037      공공용지보상채권(도로)       THE REPUBLIC OF KOREA       KOREA
     *  KR1039      공공용지보상채권(철도)       THE REPUBLIC OF KOREA       KOREA
     *  KR1041      농어촌지역개발채권           THE REPUBLIC OF KOREA       KOREA
     *  KR3103      외국환금융채권              THE REPUBLIC OF KOREA       KOREA
     *******************************************************************************/

    if (scwin.cnt == 0) {
        $c.win.alert("데이터가 없습니다 조회를 먼저 해주세요");
        return false;
    }

    // 체크된 것이 있는지 검사
    var nTrueCnt = 0;
    for (var nRow = 1; nRow <= dts_List.getTotalRow(); nRow++) {
        if (dts_List.getCellData(nRow, "CHK") == "T") {
            nTrueCnt++;
            break;
        }
    }
    if (nTrueCnt == 0) {
        $c.win.alert("선택된 종목이 없습니다.");
        return false;
    }
    var sender_ref = $c.stf.getObjectValue(edt_SENDER_REF);

    /*if(sender_ref.length != 6){
    	alert("파일 일련번호(6자리)를 넣어주세요");
    	edt_SENDER_REF.focus();
    	return false;
    }*/

    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_08);
    //file_dts_List.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 


    //var Header = "##PERMISSIONS:AA,AR,AT,AU,BE,BG,BR,CA,CH,CR,CY,CZ,DE,DK,EE,ES,FI,FR,GB,HU,ID,IT,JP,KR,LU,MX,NL,NO,PE,PL,PT,SE,SG,SK,TR,TW,US,XL,XR";//39
    var Header = ""; //39
    //var SubHeader = "##ISIN-BATCH(KR-" + sender_ref + ");" + cnt + ";;;";
    var SubHeader = "";
    file_dts_List.insertRow(0);
    file_dts_List.insertRow(1);
    file_dts_List.setCellData(1, "STD_CD", Header);
    file_dts_List.setCellData(2, "STD_CD", SubHeader);
    var file_dts_cnt = 2;
    var str = "";
    var cd = "";
    var com_eng_nm = "";
    var com_eng_abbrv = "";
    var activ_tp_cd = "";
    var cfi_cd = "";
    var exp_cd = "";
    var temp1 = "";
    var temp2 = "";
    var temp3 = "";
    var leicd = "";
    var v_grnt_dd = "";
    var v_chg_dd = "";
    for (var i = 1; i < scwin.cnt + 1; i++) {
        if (dts_List.getCellData(i, "CHK") == "T") {
            file_dts_cnt++;
            activ_tp_cd = "";
            if (dts_List.getCellData(i, "ACTIV_TP_CD") == "비활성") {
                activ_tp_cd = "D"; //"DA"

            } else if (dts_List.getCellData(i, "ACTIV_TP_CD") == "활성") {
                activ_tp_cd = dts_List.getCellData(i, "ISU_TYPE");
            }
            cd = dts_List.getCellData(i, "STD_CD").substring(0, 6);

            /*  표준코드에 따른 발행기관명 설정 ( 예외사항) */
            if (cd == "KR1011" || cd == "KR1013" ||
                cd == "KR1015" || cd == "KR1017" ||
                cd == "KR1019" || cd == "KR1021" ||
                cd == "KR1023" || cd == "KR1025" ||
                cd == "KR1027" || cd == "KR1029" ||
                cd == "KR1031" || cd == "KR1033" ||
                cd == "KR1035" || cd == "KR1037" ||
                cd == "KR1039" || cd == "KR1041" ||
                cd == "KR3103") {
                com_eng_nm = "THE REPUBLIC OF KOREA"; // 발행기관영문명
                com_eng_abbrv = "KOREA"; // 발행기관영문약명

            } else {
                com_eng_nm = dts_List.getCellData(i, "COM_ENG_NM"); // 발행기관영문명
                com_eng_abbrv = dts_List.getCellData(i, "COM_ENG_ABBRV"); // 발행기관영문약명
                if (COM_ENG_ABBRV.length > 30) {
                    com_eng_abbrv = COM_ENG_ABBRV.substring(0, 30);
                }
            }

            //채권,선물옵션 CFI 3차속성에 따른 만기일 입력
            cfi_cd = dts_List.getCellData(i, "CFI_CD");
            exp_cd = dts_List.getCellData(i, "EXP_DD");
            if (CFI_CD.substring(4, 5) == "P" || CFI_CD.substring(4, 5) == "Q") {
                exp_cd = CFI_CD.substring(4, 5);
            }

            //선물에 대한 행사가격 임시조정
            temp1 = dts_List.getCellData(i, "PROD_CLSS"); //상품분류
            temp2 = dts_List.getCellData(i, "EXER_PRC"); //행사가격
            temp3 = dts_List.getCellData(i, "EXER_PRC_CURR"); //행사가격통화
            if (temp1 == "FT" && temp2 == "0") {
                temp2 = "";
                temp3 = "";
            } else {
                temp2 = dts_List.getCellData(i, "EXER_PRC"); //행사가격
                temp3 = dts_List.getCellData(i, "EXER_PRC_CURR"); //행사가격통화

            }

            //예탁원lei코드
            leicd = dts_List.getCellData(i, "KSD_LEI");
            if (leicd != "") {
                leicd = "Korea Securities Depository~" + dts_List.getCellData(i, "KSD_LEI");
            } else {
                leicd = "";
            }

            //코드생성시점 제외(체크박스)
            if ($c.stf.getObjectValue(ckb_SEND_DD_YN) == "Y") {
                v_grnt_dd = "";
                v_chg_dd = "";
            } else {
                v_grnt_dd = ";" + dts_List.getCellData(i, "STD_CD_GRNT_DD");
                v_chg_dd = ";" + dts_List.getCellData(i, "CONTN_CHG_DD");
            }

            //이자의 종류 'Z' 할인채 이면 표면이자율 삭제
            var v_INT_TP_CD = dts_List.getCellData(i, "INT_TP_CD");
            var v_INT_RT = "";
            if (v_INT_TP_CD == "Z") {
                v_INT_RT = "";
            } else {
                v_INT_RT = dts_List.getCellData(i, "INT_RT");
            }
            str = dts_List.getCellData(i, "STD_CD") + ";" + dts_List.getCellData(i, "ACTIV_TP_CD") + ";" + dts_List.getCellData(i, "PROD_CLSS") + ";" + dts_List.getCellData(i, "ENG_ISU_NM") + ";" + dts_List.getCellData(i, "CFI_CD") + ";" + dts_List.getCellData(i, "FISN_VAL") + ";" + dts_List.getCellData(i, "PRSP_VAL") + ";" + dts_List.getCellData(i, "PAR_VAL") + ";" + dts_List.getCellData(i, "CURR_TP_CD") + ";" + dts_List.getCellData(i, "MIN_PAR_VAL") + ";" + dts_List.getCellData(i, "CONV_RTO") + ";" + dts_List.getCellData(i, "EXP_DD") + ";" + temp2 + ";" + temp3 + ";" + ";" + dts_List.getCellData(i, "INT_TP_CD") + ";" + v_INT_RT + ";" + dts_List.getCellData(i, "FSTBSTORD_INT_PAY_DD") + ";" + dts_List.getCellData(i, "INT_PAY_CYCLE") + ";" + dts_List.getCellData(i, "FST_INT_PAY_DD") + ";" + dts_List.getCellData(i, "ADD_INFO") + ";" + dts_List.getCellData(i, "MKT_ID_CD") + ";" + dts_List.getCellData(i, "LEADCOM_NM") + ";" + dts_List.getCellData(i, "LEADCOM_LEI") + ";" + dts_List.getCellData(i, "ASSTCOM_NM") + ";" + dts_List.getCellData(i, "ASSTCOM_LEI") + ";" + leicd + ";" + com_eng_nm + ";" + dts_List.getCellData(i, "COM_ENG_LEI") + ";" + com_eng_abbrv + ";" + dts_List.getCellData(i, "INTL_ORG") + ";" + dts_List.getCellData(i, "HEADQTR_ADDR1") + ";" + dts_List.getCellData(i, "HEADQTR_ADDR2") + ";" + dts_List.getCellData(i, "HEADQTR_LOCAL") + ";" + dts_List.getCellData(i, "HEADQTR_ZIPCD") + ";" + dts_List.getCellData(i, "HEADQTR_CITY") + ";" + dts_List.getCellData(i, "HEADQTR_CNTR") + ";" + dts_List.getCellData(i, "COM_REG_ADDR1") + ";" + dts_List.getCellData(i, "COM_REG_ADDR2") + ";" + dts_List.getCellData(i, "COM_REG_LOCAL") + ";" + dts_List.getCellData(i, "COM_REG_ZIPCD") + ";" + dts_List.getCellData(i, "COM_REG_CITY") + ";" + dts_List.getCellData(i, "COM_REG_CNTR") + ";" + dts_List.getCellData(i, "OLD_ISIN") + ";" + dts_List.getCellData(i, "NEW_ISIN") + ";" + dts_List.getCellData(i, "RGHT_TP_CD") + ";" + dts_List.getCellData(i, "ULY_NM") + ";" + dts_List.getCellData(i, "HEADQTR_LEI") + ";" + dts_List.getCellData(i, "HEADQTR_NM") + v_grnt_dd + v_chg_dd; //52.ISIN변경일자

            file_dts_List.insertRow(file_dts_cnt - 1);
            file_dts_List.setCellData(file_dts_cnt, "STD_CD", str);
            str = "";
        }
    }
    var toDay = $c.ut.cGetToday2();
    var toYear = toDay.substring(0, 4);
    var toMonth = toDay.substring(4, 6);
    var toDate = toDay.substring(6, 8);
    file_Grid.ExportFile2('KR' + '-' + toYear + '-' + toMonth + '-' + toDate + '-' + $c.ut.lpad(sender_ref, 6, "0") + '.txt', ';', 1032);
};
